import { CodeExample } from "@/components/docs/code-example";
import { DataGridDemo } from "@/components/docs/data-grid-demo";
import { Guidance, GuidanceBlock } from "@/components/docs/guidance";

<DataGridDemo />

  <Guidance>
    <GuidanceBlock title="When to use it">
      <ul>
        <li>Use Data Grid when records are edited in place or users need to select a two-dimensional range.</li>
        <li>Use Data Table for read-only comparison and summaries. Its native table structure needs less interaction machinery.</li>
        <li>Show the shared <a href="/components/selection-toolbar">Selection Toolbar</a> for row selection, with batch actions supplied by the consumer. Keep cell-range selection separate from row actions.</li>
        <li>The headless <code>useDataGrid</code> primitive owns selection, sorting, sizing, and atomic edit transactions. The styled component supplies Lenso cell geometry and interaction surfaces.</li>
        <li>Use the same quiet header, row height, typography, and selection surface as Data Table. Cell boundaries are faint guides for editing and range selection; the active cell and edit boundary carry the strongest emphasis.</li>
      </ul>
    </GuidanceBlock>
    <GuidanceBlock title="Editing and configuration">
      <ul>
        <li>Double-click or press Enter to edit. Enter commits; Escape cancels. Drag to select a range, use arrow keys to move, or copy and paste tab-separated cells.</li>
        <li>Set <code>readOnly</code>, <code>showRowSelection</code>, <code>showRowNumbers</code>, <code>sortable</code>, <code>cellSelection</code>, or <code>resizable</code> independently.</li>
        <li>Each column can define parsing, validation, editable rules, rendering, and a cell-specific completion callback. Validation receives the final proposed rows, the original rows, the TanStack table, and optional external data, so linked rules can be checked before any change is applied.</li>
        <li>Use <code>tableOptions</code> for TanStack Table options, <code>tableColumn</code> for per-column options, and <code>tableRef</code> to access the live API for the registered features. Grid-level callbacks remain convenient for cell commits, grouped row commits, selections, and sorting.</li>
      </ul>
    </GuidanceBlock>
  </Guidance>

<CodeExample
  code={String.raw`import { useRef } from "react";
import { DataGrid, type DataGridColumn } from "@lenso/ui/data-grid";
import type { DataGridTable } from "@lenso/primitives/data-grid";

type Company = { id: string; name: string };
type Rules = { reservedNames: ReadonlySet<string> };
const tableRef = useRef<DataGridTable<Company>>(null);
const rules: Rules = { reservedNames: new Set(["lenso"]) };

const columns: DataGridColumn<Company, Rules>[] = [
    {
      id: "name",
      header: "Company",
      getValue: (row) => row.name,
      setValue: (row, value) => ({ ...row, name: String(value) }),
      tableColumn: { sortingFn: "alphanumeric" },
      validate: (value, row, { rows, data }) => {
        const name = String(value).trim();
        if (!name) return "Name is required";
        if (data?.reservedNames.has(name.toLowerCase())) return "Name is reserved";
        return rows.some((other) => other.id !== row.id && other.name === name)
          ? "Name already exists"
          : null;
      },
    },
];

<DataGrid
    label="Companies"
    rows={rows}
    columns={columns}
    getRowId={(row) => row.id}
    onRowsChange={setRows}
    validationData={rules}
    tableOptions={{ enableMultiCellRangeSelection: false }}
    tableRef={tableRef}
    onCellEditComplete={(change) => saveCell(change)}
    onRowEditComplete={(change) => auditRow(change)}
/>;`}
  description="Validation sees the candidate transaction. The ref exposes TanStack's full table instance."
/>

