<Playground id="resize-handle" />

  <Guidance>
    <GuidanceBlock title="Usage guidance">
      <ul>
        <li>Overlay the handle on the shared pane edge instead of reserving a flex or grid track for its hit target.</li>
        <li>Keep pane sizing, persistence, and collapse state in your application.</li>
        <li>The 7px hit target is intentionally wider than its 0.5px visual indicator.</li>
        <li>Use <code>indicatorXstyle</code> when the visual line must extend beyond the handle, such as a full-height table column divider. Keep the hit target on the actual edge.</li>
        <li>Use <code>inverted</code> when increasing the controlled value moves against the pointer direction.</li>
      </ul>
    </GuidanceBlock>
    <GuidanceBlock title="Accessibility">
      <ul>
        <li>Provide an accessible name and the controlled pane ID through <code>aria-controls</code>.</li>
        <li>Arrow keys resize by <code>step</code>; Home and End select the bounds; Enter invokes the optional collapse action.</li>
      </ul>
    </GuidanceBlock>
  </Guidance>

  <CodeExample
    code={String.raw`import * as React from "react";
import { ResizeHandle } from "@lenso/ui/resize-handle";

export function InspectorLayout() {
    const [width, setWidth] = React.useState(320);

    return (
      <div style={{ display: "flex" }}>
        <aside id="inspector" style={{ position: "relative", width }}>
          Inspector
          <ResizeHandle
            aria-controls="inspector"
            aria-label="Resize inspector"
            min={240}
            max={560}
            value={width}
            onValueChange={setWidth}
            style={{ position: "absolute", insetBlock: 0, right: -5 }}
          />
        </aside>
        <main style={{ flex: 1 }}>Workspace</main>
      </div>
    );
}`}
    description="The handle is controlled and layout-independent; your application owns pane geometry."
  />

import { CodeExample } from "@/components/docs/code-example";
import { Guidance, GuidanceBlock } from "@/components/docs/guidance";
import { Playground } from "@/components/docs/playground";

<Playground id="text-field" />

  <Guidance>
    <GuidanceBlock title="Choose Text Field when">
      <ul>
        <li>People enter a short value such as a name, URL, or search query.</li>
        <li>Use Text Area for multi-line prose and Combobox for a searchable known option set.</li>
        <li>Keep the visible label even when placeholder copy provides an example.</li>
      </ul>
    </GuidanceBlock>
    <GuidanceBlock title="Validation and actions">
      <ul>
        <li>Use Description for format guidance and Error for a specific correction.</li>
        <li>Prefer read-only when the value should remain selectable; use disabled only when it is unavailable.</li>
        <li>Give Clear a task-specific accessible name and hide decorative icons.</li>
      </ul>
    </GuidanceBlock>
  </Guidance>

  <CodeExample
    code={String.raw`import { TextField } from "@lenso/ui/text-field";

<TextField.Root>
    <TextField.Label>Project name</TextField.Label>
    <TextField.Control placeholder="Untitled" />
    <TextField.Description>Visible to your team.</TextField.Description>
</TextField.Root>;`}
    description="Root connects the label, description, error, and control while preserving native input props."
  />

  <CodeExample
    code={String.raw`import { useState } from "react";
import { SearchIcon } from "lucide-react";
import { TextField } from "@lenso/ui/text-field";

function SettingsSearch() {
    const [query, setQuery] = useState("");

    return (
      <TextField.Root size="compact">
        <TextField.Label>Search settings</TextField.Label>
        <TextField.InputGroup>
          <TextField.Leading>
            <SearchIcon aria-hidden="true" size={14} />
          </TextField.Leading>
          <TextField.Control
            onValueChange={setQuery}
            placeholder="Search…"
            type="search"
            value={query}
          />
          {query ? (
            <TextField.Trailing>
              <TextField.Clear aria-label="Clear settings search" onClear={() => setQuery("")} />
            </TextField.Trailing>
          ) : null}
        </TextField.InputGroup>
      </TextField.Root>
    );
}`}
    description="Compose search from the same Text Field parts; no separate Search Field component is needed."
  />

